SELECT CASE WHEN event_type IN ('page_view', 'add_to_cart') THEN 'priority' ELSE 'other' END AS event_type_group, session_id, MAX(duration_sec) - MIN(duration_sec) AS duration_sec_range, MAX(duration_sec) AS max_duration_sec, ROUND((100 * SUM(CASE WHEN event_type = 'purchase' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_purchase FROM web_events GROUP BY CASE WHEN event_type IN ('page_view', 'add_to_cart') THEN 'priority' ELSE 'other' END, session_id ORDER BY duration_sec_range DESC, event_type_group, session_id LIMIT 1;
